-- DDL - Estrutura do Banco de Dados UAI FRILA
CREATE TABLE paises (id SERIAL PRIMARY KEY, nome VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE estados (id SERIAL PRIMARY KEY, pg_id INT, nome VARCHAR(100) NOT NULL, sigla CHAR(2) NOT NULL UNIQUE);
CREATE TABLE cidades (id SERIAL PRIMARY KEY, estado_id INT REFERENCES estados(id) ON DELETE CASCADE, nome VARCHAR(100) NOT NULL, ativo BOOLEAN DEFAULT FALSE);
CREATE TABLE bairros (id SERIAL PRIMARY KEY, cidade_id INT REFERENCES cidades(id) ON DELETE CASCADE, nome VARCHAR(100) NOT NULL);
CREATE TABLE usuarios (id SERIAL PRIMARY KEY, whatsapp VARCHAR(20) NOT NULL UNIQUE, senha VARCHAR(255) NOT NULL, nome_completo VARCHAR(150), cpf VARCHAR(14) UNIQUE, nome_fantasia VARCHAR(150), cnpj VARCHAR(18) UNIQUE, is_freela BOOLEAN DEFAULT FALSE, is_contratante BOOLEAN DEFAULT FALSE, is_admin BOOLEAN DEFAULT FALSE, role VARCHAR(50) DEFAULT 'USER', funcao_principal VARCHAR(100), valor_hora_base NUMERIC(10,2), bio TEXT, como_chega VARCHAR(50), custo_transporte NUMERIC(10,2), tem_mei BOOLEAN DEFAULT FALSE, aceitou_termos BOOLEAN DEFAULT FALSE, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE vagas (id SERIAL PRIMARY KEY, contratante_id INT REFERENCES usuarios(id) ON DELETE CASCADE, funcao VARCHAR(100) NOT NULL, data_hora TIMESTAMP NOT NULL, horas_estimadas INT NOT NULL, valor_hora_limpo NUMERIC(10,2) NOT NULL, ajuda_custo_transporte NUMERIC(10,2) DEFAULT 0.00, endereco_completo TEXT NOT NULL, bairro_id INT REFERENCES bairros(id), status VARCHAR(50) DEFAULT 'PENDENTE');
CREATE TABLE candidaturas (id SERIAL PRIMARY KEY, vaga_id INT REFERENCES vagas(id) ON DELETE CASCADE, freela_id INT REFERENCES usuarios(id) ON DELETE CASCADE, status VARCHAR(50) DEFAULT 'AGUARDANDO', UNIQUE(vaga_id, freela_id));
CREATE TABLE trampos (id SERIAL PRIMARY KEY, vaga_id INT REFERENCES vagas(id) ON DELETE CASCADE, freela_id INT REFERENCES usuarios(id) ON DELETE CASCADE, codigo_inicio VARCHAR(10) NOT NULL, codigo_fim VARCHAR(10) NOT NULL, ponto_inicio TIMESTAMP, ponto_fim TIMESTAMP, status VARCHAR(50) DEFAULT 'AGUARDANDO_PAGAMENTO');
CREATE TABLE avaliacoes (id SERIAL PRIMARY KEY, trampo_id INT REFERENCES trampos(id) ON DELETE CASCADE, avaliador_id INT REFERENCES usuarios(id) ON DELETE CASCADE, avalisdo_id INT REFERENCES usuarios(id) ON DELETE CASCADE, nota INT CHECK (nota >= 1 AND nota <= 5), comentario TEXT, tipo VARCHAR(20) NOT NULL);
CREATE TABLE mensagens_chat (id SERIAL PRIMARY KEY, vaga_id INT REFERENCES vagas(id) ON DELETE CASCADE, remetente_id INT REFERENCES usuarios(id) ON DELETE CASCADE, destinatario_id INT REFERENCES usuarios(id) ON DELETE CASCADE, conteudo TEXT NOT NULL, enviado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE variaveis_ambiente (chave VARCHAR(100) PRIMARY KEY, valor VARCHAR(255) NOT NULL, descricao TEXT);
